SourceObjectCatalogSummary0x49da08 source_object_catalog_summary_0x49da08() {
	const std::vector<SourceObjectRecord0x4c> &records = source_object_catalog_0x49da08();
	SourceObjectCatalogSummary0x49da08 summary;
	summary.record_count = int32_t(records.size());
	summary.source_record_copy_size_bytes = SOURCE_OBJECT_RECORD_COPY_SIZE_BYTES_0X4C;
	std::map<int32_t, int32_t> mine_subtype_counts;
	for (const SourceObjectRecord0x4c &record : records) {
		if (record.source == "objects.txt") {
			summary.objects_txt_record_count += 1;
		}
		if (record.rand_trn_backed) {
			summary.rand_trn_backed_record_count += 1;
		}
		if (record.type_id_0x1c == 53) {
			summary.mine_type53_record_count += 1;
			mine_subtype_counts[record.subtype_0x20] += 1;
		}
	}
	for (const auto &entry : mine_subtype_counts) {
		if (entry.second > 1) {
			summary.mine_type53_ambiguous_subtype_count += 1;
		}
	}
	summary.descriptor_only_mine_identity_ambiguous = summary.mine_type53_ambiguous_subtype_count > 0;
	return summary;
}

